  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Maraviroc, despite P-gp-mediated nonlinear absorption, has an absolute oral bioavailability of 33% in healthy volunteers, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Indinavir has an absolute oral bioavailability of 65% in healthy subjects, a direct human measurement well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Garenoxacin has an absolute oral bioavailability of 92% after a single oral dose in humans, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Levodopa absolute bioavailability under fasted conditions averaged 80.4% in healthy young volunteers, directly matching the fasted query condition and exceeding the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol oral bioavailability is described as excellent in patients, exceeding the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "DPP-4 inhibitors are well absorbed orally with human bioavailability of 75–87%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence, with high assay-transfer scores, reports absolute oral bioavailability values at or above 23–33% and mostly above 60%, supporting F ≥20% for the query. No affirmative evidence indicates F <20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule or a close cephalosporin analogue.",
    "The influence of the 3-((1H-tetrazol-5-ylthio)methyl) substituent and the zwitterionic cephalosporin scaffold on intestinal absorption is not directly covered by the retrieved evidence.",
    "Fasted-state-specific data are available only for levodopa among the evidence set; other records do not specify prandial state."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

